import json,re,html
from html.parser import HTMLParser
from pathlib import Path
s=json.loads(Path('source.json').read_text()); a=json.loads(Path('answer.json').read_text()); r=json.loads(Path('reference-targets.json').read_text())
class P(HTMLParser):
 def __init__(self): super().__init__(convert_charrefs=True);self.text=[];self.tags=[]
 def handle_data(self,t): self.text.append(t)
 def handle_starttag(self,t,attrs): self.tags.append((t,attrs))
def parse(x):
 p=P();p.feed(x or '');return p
allowed=set('p br table thead tbody tfoot tr th td b strong i em u sup sub ul ol li div span blockquote'.split())
errors=[]
for src,d in zip(s,a):
 n=d['number'];pst=parse(d['proposed_xml']);source=''.join(parse(src['source_xml']).text);prop=''.join(pst.text)
 for k in ['code_id','source_id','source_sha256','number']:
  if d[k]"'!=src[k]: errors.append((n,k))
 for tag,attrs in pst.tags:
  if tag not in allowed: errors.append((n,'"'tag',tag))
