   if k not in ['rowspan','colspan'] or not v.isdigit(): errors.append((n,'attr',tag,k,v))
 if d['status']=='retained_unchanged':
  assert d['proposed_xml'] is None
  assert d['substantive_impact']['classification'] in ['retained_necessary','reserved']
 else: assert d['status']=='rewrite_draft' and d['proposed_xml']
 imp=d['substantive_impact'];assert imp['version']==1
 for k in ['assessment','scope_limitations','new_burdens_review']:
  if len(imp[k])<40: errors.append((n,'short',k))
 if src['benefit_check_required'] and len(d.get('benefit_review',''))<100: errors.append((n,'benefit'))
 for j,e in enumerate(imp['effects']):
  for k,tx in [('source_quote',source),('proposed_quote',prop)]:
   if len(e[k])<12 or e[k] not in tx: errors.append((n,j,k,e[k]))
  if not re.fullmatch('[a-z0-9]+(?:-[a-z0-9]+)+',e['measure_id']) or not 6<=len(e['measure_id'])<=96: errors.append((n,'measure',e['measure_id']))
 key=d['code_id']+'|'+d['source_id']
 if [v['target_key'] for v in d['reference_checks']]"'!=r['"'requirements'][key]: errors.append((n,'reference_list'))
 for c in d['reference_checks']:
  if c['view_sha256']"'!=r['"'targets'][c['target_key']]['view_sha256'] or len(c['assessment'])<80: errors.append((n,'reference_value'))
 if d.get('change_type')=='normative_reduction':
  assert d['reform_policy_id']=='editorial_direction_2026_10_19'
  assert d['removed_provisions'] and all(len(z)>=30 for z in d['removed_provisions'])
 if d.get('change_type')=='full_repeal':
  assert d['repeal_policy_id']=='editorial_direction_2026_10_19' and len(d['repeal_scope'])>=30
  assert prop.startswith(('Le présent article est abrogé','Abrogé'))
 print(n,'source',len(source),'proposition',len(prop),d['status'],imp['classification'],'effects',len(imp['effects']),'refs',len(d['reference_checks']))
print('ERRORS',json.dumps(errors,ensure_ascii=False,indent=2))
assert len(a)==12 and not errors
